// Open/close:
function togglePopover(triggerId) {
  var wrap = document.getElementById(triggerId).closest('.ds-popover-wrap');
  var content = wrap.querySelector('.ds-popover-content');
  var isOpen = content.classList.toggle('open');
  var trigger = wrap.querySelector('.ds-popover-trigger');
  trigger.setAttribute('aria-expanded', isOpen);
}
// Close on outside click:
document.addEventListener('click', function(e) {
  document.querySelectorAll('.ds-popover-content.open').forEach(function(p) {
    if (!p.closest('.ds-popover-wrap').contains(e.target)) {
      p.classList.remove('open');
    }
  });
});
// Close on Escape:
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') document.querySelectorAll('.ds-popover-content.open').forEach(function(p) { p.classList.remove('open'); });
});
